import { CHARSET } from './constants.mjs';
import { verifyChecksum } from './checksum.mjs';

const CHARACTER_INDEX = new Map(
  [...CHARSET].map((character, index) => [character, index]),
);

function isPrintableAscii(value) {
  for (const character of value) {
    const codePoint = character.charCodeAt(0);

    if (codePoint < 33 || codePoint > 126) {
      return false;
    }
  }

  return true;
}

function hasMixedCase(value) {
  return value !== value.toLowerCase() && value !== value.toUpperCase();
}

function decodeDataPart(dataPart) {
  const decoded = [];

  for (const character of dataPart) {
    const value = CHARACTER_INDEX.get(character);

    if (value === undefined) {
      return null;
    }

    decoded.push(value);
  }

  return decoded;
}

export function bech32Decode(value) {
  if (!isPrintableAscii(value) || hasMixedCase(value) || value.length > 90) {
    return [null, null];
  }

  const normalized = value.toLowerCase();
  const separatorIndex = normalized.lastIndexOf('1');

  if (separatorIndex < 1 || separatorIndex + 7 > normalized.length) {
    return [null, null];
  }

  const hrp = normalized.slice(0, separatorIndex);
  const data = decodeDataPart(normalized.slice(separatorIndex + 1));

  if (data === null || !verifyChecksum(hrp, data)) {
    return [null, null];
  }

  return [hrp, data.slice(0, -6)];
}

