import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

import { bech32Decode } from './lib/bech32/decode.mjs';
import {
  getErrorText,
  getHelpText,
  getProgramName,
  parseArguments,
} from './lib/cli/argparse_like.mjs';
import { formatPythonTuple } from './lib/python/repr.mjs';

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const programName = getProgramName(scriptPath);
  const parsed = parseArguments(argv);

  if (parsed.kind === 'help') {
    process.stdout.write(getHelpText(programName));
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(getErrorText(programName, parsed.message));
    return 2;
  }

  const [hrp, data] = bech32Decode(parsed.argumentsObject.a);
  process.stdout.write(`${formatPythonTuple(hrp, data)}\n`);
  return 0;
}

const isDirectExecution =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(resolve(process.argv[1])).href;

if (isDirectExecution) {
  process.exitCode = main();
}

